func profileRealityCreds(nodes []*model.NodeInfo, profileID string) (pub, sid string) {
	for _, n := range nodes {
		for _, ib := range n.Inbounds {
			if ib.ProfileID == profileID && ib.ServerPubKey != "" {
				return ib.ServerPubKey, ib.ShortID
			}
		}
	}
	return "", ""
}

